function mergeBase(parents, a, b) {
  const ancestorsOfA = new Set();
  const stack = [a];
  while (stack.length) {
    const c = stack.pop();
    if (ancestorsOfA.has(c)) continue;
    ancestorsOfA.add(c);
    stack.push(...(parents[c] || []));
  }
  const queue = [b];
  const visited = new Set();
  while (queue.length) {
    const c = queue.shift();
    if (ancestorsOfA.has(c)) return c;
    if (visited.has(c)) continue;
    visited.add(c);
    queue.push(...(parents[c] || []));
  }
  return null;
}

