def big_files(numstat, limit):
    out = []
    for line in numstat.splitlines():
        if not line.strip():
            continue
        added, deleted, path = line.split("\t", 2)
        if added == "-" or deleted == "-":
            continue
        total = int(added) + int(deleted)
        if total > limit:
            out.append((-total, path))
    out.sort()
    return [p for _, p in out]
